CREATE OR REPLACE FUNCTION public.answer_escalation(p_id uuid, p_pharmacist uuid, p_reply text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_id      uuid;
  v_session uuid;
  v_owner   uuid;
begin
  if p_reply is null or length(trim(p_reply)) = 0 then
    raise exception 'reply must not be empty';
  end if;

  -- the "and status = 'pending'" makes two pharmacists answering at once safe: only one wins
  update public.escalations
     set status = 'answered', reply = p_reply, pharmacist_id = p_pharmacist, answered_at = now()
   where id = p_id and status = 'pending'
  returning id, session_id, user_id into v_id, v_session, v_owner;

  if v_id is null then
    return null;
  end if;

  -- the pharmacist's message belongs to the session OWNER (user_id); who answered is in escalations.pharmacist_id
  insert into public.chat_messages (session_id, user_id, role, content)
  values (v_session, v_owner, 'pharmacist', p_reply);

  return v_id;
end;
$function$;

revoke all on function "public"."answer_escalation"(p_id uuid, p_pharmacist uuid, p_reply text) from public, anon, authenticated, service_role;
grant execute on function "public"."answer_escalation"(p_id uuid, p_pharmacist uuid, p_reply text) to "service_role";

CREATE OR REPLACE FUNCTION public.hybrid_search(query_embedding extensions.vector, query_text text, match_count integer DEFAULT 20, drug_filter text DEFAULT NULL::text)
 RETURNS TABLE(chunk_id uuid, content text, drug_name text, section text, vector_rank integer, keyword_rank integer, rrf_score double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'extensions'
AS $function$
  -- v = the 20 chunks whose MEANING is closest to the question.
  -- "<=>" is cosine distance (0 = same direction), so ascending order = most similar first.
  -- rank 1 = best match. Optional drug_filter keeps only one drug's chunks.
  with v as (
    select c.id,
           row_number() over (order by c.embedding <=> query_embedding) as rank
    from drug_chunks c
    where c.embedding is not null
      and (drug_filter is null or c.drug_name = drug_filter)
    order by c.embedding <=> query_embedding
    limit 20
  ),
  -- k = the 20 chunks that contain the question's WORDS (Postgres full-text search on fts).
  -- websearch_to_tsquery understands normal typing ("warfarin bleeding", "-alcohol", "quotes").
  -- ts_rank scores how well a chunk matches; higher = better, so rank 1 = best.
  -- An empty query_text matches nothing here.
  k as (
    select c.id,
           row_number() over (
             order by ts_rank(c.fts, websearch_to_tsquery('english', query_text)) desc
           ) as rank
    from drug_chunks c
    where c.fts @@ websearch_to_tsquery('english', query_text)
      and (drug_filter is null or c.drug_name = drug_filter)
    order by ts_rank(c.fts, websearch_to_tsquery('english', query_text)) desc
    limit 20
  ),
  -- fused = every chunk found by v, by k, or by both (full outer join).
  -- RRF: each list gives 1 / (60 + rank); a list that did not find the chunk gives 0.
  -- A chunk found by BOTH lists gets two shares, so it rises to the top.
  fused as (
    select coalesce(v.id, k.id) as id,
           v.rank as vector_rank,
           k.rank as keyword_rank,
           coalesce(1.0 / (60 + v.rank), 0) + coalesce(1.0 / (60 + k.rank), 0) as rrf_score
    from v
    full outer join k on k.id = v.id
  )
  -- Join back to drug_chunks for the text the answer needs; best fused score first.
  select f.id,
         c.content,
         c.drug_name,
         c.section,
         f.vector_rank::int,
         f.keyword_rank::int,
         f.rrf_score::float
  from fused f
  join drug_chunks c on c.id = f.id
  order by f.rrf_score desc
  limit match_count;
$function$;

revoke all on function "public"."hybrid_search"(query_embedding extensions.vector, query_text text, match_count integer, drug_filter text) from public, anon, authenticated, service_role;
grant execute on function "public"."hybrid_search"(query_embedding extensions.vector, query_text text, match_count integer, drug_filter text) to "service_role";

CREATE OR REPLACE FUNCTION public.is_pharmacist()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1
    from public.users u
    where u.id = auth.uid()
      and u.role::text in ('vendor', 'admin')      -- ADJUST: your role values
  );
$function$;

revoke all on function "public"."is_pharmacist"() from public, anon, authenticated, service_role;
grant execute on function "public"."is_pharmacist"() to "authenticated", "service_role";

CREATE OR REPLACE FUNCTION public.login_user(user_email text, user_password text)
 RETURNS TABLE(id uuid, email text, name text, phone text, role text, company_name text, address text, city text, state text, email_verified boolean, phone_verified boolean, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, last_login timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r RECORD;
  matched_id uuid;
  has_google_only boolean := false;
BEGIN
  -- Same email can exist once per role (user/vendor/...), so check each
  -- active row and pick the one whose password actually matches.
  FOR r IN
    SELECT u.id, u.password_hash
    FROM public.users u
    WHERE u.email = lower(trim(user_email)) AND u.is_active = true
  LOOP
    IF r.password_hash IS NULL THEN
      has_google_only := true;
    ELSIF encode(digest(user_password || split_part(r.password_hash, ':', 1), 'sha256'), 'hex')
          = split_part(r.password_hash, ':', 2) THEN
      matched_id := r.id;
      EXIT;
    END IF;
  END LOOP;

  IF matched_id IS NULL THEN
    IF has_google_only THEN
      RAISE EXCEPTION 'This account signs in with Google. Use Continue with Google.';
    END IF;
    RAISE EXCEPTION 'Invalid email or password.';
  END IF;

  UPDATE public.users SET last_login = NOW() WHERE public.users.id = matched_id;

  RETURN QUERY
  SELECT u.id, u.email, u.name, u.phone, u.role, u.company_name, u.address, u.city, u.state,
         u.email_verified, u.phone_verified, u.is_active, u.created_at, u.updated_at, u.last_login
  FROM public.users u
  WHERE u.id = matched_id;
END;
$function$;

revoke all on function "public"."login_user"(user_email text, user_password text) from public, anon, authenticated, service_role;
grant execute on function "public"."login_user"(user_email text, user_password text) to "anon", "authenticated", public, "service_role";

CREATE OR REPLACE FUNCTION public.touch_chat_session()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  update public.chat_sessions set updated_at = now() where id = new.session_id;
  return new;
end;
$function$;

revoke all on function "public"."touch_chat_session"() from public, anon, authenticated, service_role;
